// Minimal Neon Runner game
const canvas = document.getElementById('game');
const ctx = canvas.getContext('2d');
canvas.width = canvas.clientWidth;
canvas.height = canvas.clientHeight;

// Player
const player = {
  w: 30,
  h: 30,
  x: 50,
  y: canvas.height - 30,
  vy: 0,
  gravity: 0.8,
  jumpStrength: -15,
  sliding: false,
  slideTimer: 0,
  update() {
    if (this.sliding) {
      this.slideTimer -= 1;
      if (this.slideTimer <= 0) this.sliding = false;
    }
    this.vy += this.gravity;
    this.y += this.vy;
    if (this.y > canvas.height - this.h) this.y = canvas.height - this.h, this.vy = 0;
  },
  draw() {
    ctx.fillStyle = '#0ff';
    ctx.fillRect(this.x, this.y, this.w, this.sliding ? this.h/2 : this.h);
  },
  jump() { if (this.y >= canvas.height - this.h) this.vy = this.jumpStrength; },
  slide() { if (!this.sliding && this.y >= canvas.height - this.h) { this.sliding = true; this.slideTimer = 20; } }
};

// Obstacles
const obstacles = [];
function spawnObstacle() {
  const type = Math.random() < 0.5 ? 'low' : 'high';
  const w = 20, h = type === 'low' ? 30 : 30;
  const y = type === 'low' ? canvas.height - h : canvas.height - h - player.h - 10;
  obstacles.push({ x: canvas.width, y, w, h, type });
}
let spawnTimer = 0;

function updateObstacles() {
  spawnTimer--;
  if (spawnTimer <= 0) { spawnObstacle(); spawnTimer = 60 + Math.random()*60; }
  for (let i = obstacles.length - 1; i >= 0; i--) {
    const o = obstacles[i];
    o.x -= 5;
    if (o.x + o.w < 0) obstacles.splice(i, 1);
  }
}

function drawObstacles() {
  ctx.fillStyle = '#f0f';
  obstacles.forEach(o => ctx.fillRect(o.x, o.y, o.w, o.h));
}

function checkCollision() {
  for (const o of obstacles) {
    const pw = player.w;
    const ph = player.sliding ? player.h/2 : player.h;
    if (player.x < o.x + o.w && player.x + pw > o.x &&
        player.y < o.y + o.h && player.y + ph > o.y) {
      return true;
    }
  }
  return false;
}

let score = 0;
let gameOver = false;
function loop() {
  if (gameOver) return;
  ctx.clearRect(0,0,canvas.width,canvas.height);
  player.update();
  player.draw();
  updateObstacles();
  drawObstacles();
  if (checkCollision()) { gameOver = true; alert('Game Over! Score: ' + Math.floor(score)); return; }
  score += 0.1;
  ctx.fillStyle = '#fff';
  ctx.font = '16px monospace';
  ctx.fillText('Score: ' + Math.floor(score), 10, 20);
  requestAnimationFrame(loop);
}

// Controls
window.addEventListener('keydown', e => {
  if (e.code === 'Space' || e.code === 'ArrowUp') player.jump();
  else if (e.code === 'ArrowDown') player.slide();
});

// Start
requestAnimationFrame(loop);
